// Des: State store: caps counters, idempotent sends, chats, queue, log
// Flo: open + migrate > count actions in windows > begin send once > save chats > queue jobs > append log
// I/O: now ms + text (caller) > rows in the SQLite file (one writer)
// ===================================================================
const std = @import("std"); const sqli = @import("st-stor-sqli.zig"); const pace = @import("ru-huma-pace.zig");
const CF = .{ .mins = 60000, .hour = 3600000, .dayz = 86400000, .keyl = 32 };
const STEPS = [_][:0]const u8{ "CREATE TABLE meta(k TEXT PRIMARY KEY, v TEXT NOT NULL);CREATE TABLE acts(id INTEGER PRIMARY KEY, ts INTEGER NOT NULL, kind TEXT NOT NULL);CREATE INDEX acts_ts ON acts(ts);CREATE TABLE sends(key TEXT PRIMARY KEY, chat TEXT NOT NULL, state TEXT NOT NULL, ts INTEGER NOT NULL);CREATE TABLE msgs(id INTEGER PRIMARY KEY, chat TEXT NOT NULL, who TEXT NOT NULL, body TEXT NOT NULL, ts INTEGER NOT NULL);CREATE INDEX msgs_chat ON msgs(chat, id);CREATE TABLE queue(id INTEGER PRIMARY KEY, uuid TEXT NOT NULL, ts INTEGER NOT NULL, job TEXT NOT NULL, args TEXT NOT NULL, state TEXT NOT NULL);CREATE TABLE logz(id INTEGER PRIMARY KEY, ts INTEGER NOT NULL, lvl TEXT NOT NULL, job TEXT NOT NULL, msg TEXT NOT NULL);CREATE TABLE drafts(id INTEGER PRIMARY KEY, chat TEXT NOT NULL, body TEXT NOT NULL, ts INTEGER NOT NULL, state TEXT NOT NULL);", "CREATE TABLE flow(id INTEGER PRIMARY KEY, uuid TEXT NOT NULL, name TEXT NOT NULL, ts INTEGER NOT NULL, state TEXT NOT NULL);CREATE TABLE item(id INTEGER PRIMARY KEY, flow INTEGER NOT NULL, seq INTEGER NOT NULL, job TEXT NOT NULL, args TEXT NOT NULL, risk TEXT NOT NULL, appr INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', tries INTEGER NOT NULL DEFAULT 0, ts INTEGER NOT NULL);CREATE INDEX item_flow ON item(flow, seq);CREATE TABLE chatf(chat TEXT PRIMARY KEY, ts INTEGER NOT NULL);" };
pub const Begin = enum { fresh, pend, dup };
pub const Msgz = struct { who: []const u8, body: []const u8, ts: i64 };
pub const Qrow = struct { id: i64, uuid: []const u8, job: []const u8, args: []const u8 };
pub const Lrow = struct { ts: i64, lvl: []const u8, job: []const u8, msg: []const u8 };
pub fn sendKey(chat: []const u8, text: []const u8) [CF.keyl]u8 { var hsh = std.crypto.hash.sha2.Sha256.init(.{}); hsh.update(chat); hsh.update("\x00"); hsh.update(text); var dig: [32]u8 = undefined; hsh.final(&dig); return std.fmt.bytesToHex(dig[0 .. CF.keyl / 2].*, .lower); }
pub const Stor = struct { dbzz: sqli.Db,
pub fn open(allo: std.mem.Allocator, path: [:0]const u8) !Stor { var dbzz = try sqli.Db.open(path); errdefer dbzz.close(); try dbzz.migr(allo, &STEPS); return .{ .dbzz = dbzz }; }
pub fn close(self: *Stor) void { self.dbzz.close(); }
pub fn metaSet(self: *Stor, key: []const u8, valu: []const u8) !void { var stm = try self.dbzz.prep("INSERT OR REPLACE INTO meta(k,v) VALUES(?,?);"); defer stm.fini(); try stm.bindText(1, key); try stm.bindText(2, valu); _ = try stm.step(); }
pub fn metaGet(self: *Stor, allo: std.mem.Allocator, key: []const u8) !?[]u8 { var stm = try self.dbzz.prep("SELECT v FROM meta WHERE k=?;"); defer stm.fini(); try stm.bindText(1, key); if (!try stm.step()) return null; return try allo.dupe(u8, stm.colText(0)); }
pub fn firstSeen(self: *Stor, allo: std.mem.Allocator, now_ms: i64) !i64 { if (try self.metaGet(allo, "first_ms")) |txt| { defer allo.free(txt); return std.fmt.parseInt(i64, txt, 10) catch now_ms; } var buf: [24]u8 = undefined; try self.metaSet("first_ms", try std.fmt.bufPrint(&buf, "{d}", .{now_ms})); return now_ms; }
pub fn actAdd(self: *Stor, now_ms: i64, kind: []const u8) !void { var stm = try self.dbzz.prep("INSERT INTO acts(ts,kind) VALUES(?,?);"); defer stm.fini(); try stm.bindInt(1, now_ms); try stm.bindText(2, kind); _ = try stm.step(); }
fn cntSince(self: *Stor, sqlz: [:0]const u8, since: i64) !u32 { var stm = try self.dbzz.prep(sqlz); defer stm.fini(); try stm.bindInt(1, since); if (!try stm.step()) return 0; return @intCast(stm.colInt(0)); }
pub fn statGet(self: *Stor, allo: std.mem.Allocator, now_ms: i64) !pace.Stat { const first = try self.firstSeen(allo, now_ms); var lastz: i64 = 0; var stm = try self.dbzz.prep("SELECT COALESCE(MAX(ts),0) FROM acts WHERE kind IN ('send','newc');"); defer stm.fini(); if (try stm.step()) lastz = stm.colInt(0); return .{ .first_ms = first, .hour_cnt = try self.cntSince("SELECT COUNT(*) FROM acts WHERE kind IN ('send','newc') AND ts>?;", now_ms - CF.hour), .minu_cnt = try self.cntSince("SELECT COUNT(*) FROM acts WHERE kind IN ('send','newc') AND ts>?;", now_ms - CF.mins), .day_cnt = try self.cntSince("SELECT COUNT(*) FROM acts WHERE kind IN ('send','newc') AND ts>?;", now_ms - CF.dayz), .newc_cnt = try self.cntSince("SELECT COUNT(*) FROM acts WHERE kind='newc' AND ts>?;", now_ms - CF.dayz), .reac_cnt = try self.cntSince("SELECT COUNT(*) FROM acts WHERE kind='react' AND ts>?;", now_ms - CF.dayz), .upld_cnt = try self.cntSince("SELECT COUNT(*) FROM acts WHERE kind='upld' AND ts>?;", now_ms - CF.dayz), .last_ms = lastz }; }
pub fn sendBegin(self: *Stor, chat: []const u8, text: []const u8, now_ms: i64) !Begin { const key = sendKey(chat, text); var ins = try self.dbzz.prep("INSERT OR IGNORE INTO sends(key,chat,state,ts) VALUES(?,?,'pend',?);"); defer ins.fini(); try ins.bindText(1, &key); try ins.bindText(2, chat); try ins.bindInt(3, now_ms); _ = try ins.step(); if (self.dbzz.changes() == 1) return .fresh; var sel = try self.dbzz.prep("SELECT state FROM sends WHERE key=?;"); defer sel.fini(); try sel.bindText(1, &key); if (!try sel.step()) return error.Fail; return if (std.mem.eql(u8, sel.colText(0), "sent")) .dup else .pend; }
pub fn sendDone(self: *Stor, chat: []const u8, text: []const u8, now_ms: i64) !void { const key = sendKey(chat, text); var stm = try self.dbzz.prep("UPDATE sends SET state='sent', ts=? WHERE key=?;"); defer stm.fini(); try stm.bindInt(1, now_ms); try stm.bindText(2, &key); _ = try stm.step(); if (self.dbzz.changes() == 0) return error.Fail; try self.actAdd(now_ms, "send"); }
pub fn sendDrop(self: *Stor, chat: []const u8, text: []const u8) !void { const key = sendKey(chat, text); var stm = try self.dbzz.prep("DELETE FROM sends WHERE key=? AND state='pend';"); defer stm.fini(); try stm.bindText(1, &key); _ = try stm.step(); }
pub fn msgAdd(self: *Stor, chat: []const u8, who: []const u8, body: []const u8, now_ms: i64) !void { var stm = try self.dbzz.prep("INSERT INTO msgs(chat,who,body,ts) VALUES(?,?,?,?);"); defer stm.fini(); try stm.bindText(1, chat); try stm.bindText(2, who); try stm.bindText(3, body); try stm.bindInt(4, now_ms); _ = try stm.step(); }
pub fn msgTail(self: *Stor, aren: std.mem.Allocator, chat: []const u8, lim: u32) ![]Msgz { var stm = try self.dbzz.prep("SELECT who,body,ts FROM (SELECT id,who,body,ts FROM msgs WHERE chat=? ORDER BY id DESC LIMIT ?) ORDER BY id ASC;"); defer stm.fini(); try stm.bindText(1, chat); try stm.bindInt(2, lim); var out: std.ArrayList(Msgz) = .empty; while (try stm.step()) try out.append(aren, .{ .who = try aren.dupe(u8, stm.colText(0)), .body = try aren.dupe(u8, stm.colText(1)), .ts = stm.colInt(2) }); return out.items; }
pub fn queAdd(self: *Stor, uuid: []const u8, now_ms: i64, job: []const u8, args: []const u8) !void { var stm = try self.dbzz.prep("INSERT INTO queue(uuid,ts,job,args,state) VALUES(?,?,?,?,'todo');"); defer stm.fini(); try stm.bindText(1, uuid); try stm.bindInt(2, now_ms); try stm.bindText(3, job); try stm.bindText(4, args); _ = try stm.step(); }
pub fn queNext(self: *Stor, aren: std.mem.Allocator) !?Qrow { var stm = try self.dbzz.prep("SELECT id,uuid,job,args FROM queue WHERE state IN ('todo','busy') ORDER BY id LIMIT 1;"); defer stm.fini(); if (!try stm.step()) return null; return .{ .id = stm.colInt(0), .uuid = try aren.dupe(u8, stm.colText(1)), .job = try aren.dupe(u8, stm.colText(2)), .args = try aren.dupe(u8, stm.colText(3)) }; }
pub fn queSet(self: *Stor, idz: i64, state: []const u8) !void { var stm = try self.dbzz.prep("UPDATE queue SET state=? WHERE id=?;"); defer stm.fini(); try stm.bindText(1, state); try stm.bindInt(2, idz); _ = try stm.step(); if (self.dbzz.changes() == 0) return error.Fail; }
pub fn purge(self: *Stor, now_ms: i64, keep_days: u32) !u32 { if (keep_days == 0) return 0; var stm = try self.dbzz.prep("DELETE FROM msgs WHERE ts<?;"); defer stm.fini(); try stm.bindInt(1, now_ms - @as(i64, keep_days) * CF.dayz); _ = try stm.step(); return @intCast(self.dbzz.changes()); }
pub fn kindSince(self: *Stor, kind: []const u8, since: i64) !u32 { var stm = try self.dbzz.prep("SELECT COUNT(*) FROM acts WHERE kind=? AND ts>?;"); defer stm.fini(); try stm.bindText(1, kind); try stm.bindInt(2, since); if (!try stm.step()) return 0; return @intCast(stm.colInt(0)); }
pub fn lastSend(self: *Stor, aren: std.mem.Allocator) !?[]const u8 { var stm = try self.dbzz.prep("SELECT chat FROM sends WHERE state='sent' ORDER BY ts DESC, rowid DESC LIMIT 1;"); defer stm.fini(); if (!try stm.step()) return null; return try aren.dupe(u8, stm.colText(0)); }
pub fn backup(self: *Stor, path: []const u8) !void { var stm = try self.dbzz.prep("VACUUM INTO ?;"); defer stm.fini(); try stm.bindText(1, path); _ = try stm.step(); }
pub fn logAdd(self: *Stor, now_ms: i64, lvl: []const u8, job: []const u8, msg: []const u8) !void { var stm = try self.dbzz.prep("INSERT INTO logz(ts,lvl,job,msg) VALUES(?,?,?,?);"); defer stm.fini(); try stm.bindInt(1, now_ms); try stm.bindText(2, lvl); try stm.bindText(3, job); try stm.bindText(4, msg); _ = try stm.step(); }
pub fn logTail(self: *Stor, aren: std.mem.Allocator, lim: u32) ![]Lrow { var stm = try self.dbzz.prep("SELECT ts,lvl,job,msg FROM (SELECT id,ts,lvl,job,msg FROM logz ORDER BY id DESC LIMIT ?) ORDER BY id ASC;"); defer stm.fini(); try stm.bindInt(1, lim); var out: std.ArrayList(Lrow) = .empty; while (try stm.step()) try out.append(aren, .{ .ts = stm.colInt(0), .lvl = try aren.dupe(u8, stm.colText(1)), .job = try aren.dupe(u8, stm.colText(2)), .msg = try aren.dupe(u8, stm.colText(3)) }); return out.items; }
pub fn haltSet(self: *Stor, now_ms: i64, why: []const u8) !void { try self.metaSet("halt_why", why); var buf: [24]u8 = undefined; try self.metaSet("halt_ms", try std.fmt.bufPrint(&buf, "{d}", .{now_ms})); }
pub fn haltGet(self: *Stor, allo: std.mem.Allocator) !?[]u8 { const why = try self.metaGet(allo, "halt_why") orelse return null; if (why.len == 0) { allo.free(why); return null; } return why; }
pub fn haltClear(self: *Stor) !void { try self.metaSet("halt_why", ""); } };
